namespace ApiVault.Core.DTOs;

/// <summary>
/// Sensitive fields (token, password, username, notes, URL) exist only inside <see cref="EncryptedPayload"/>.
/// The secret Id is generated by the browser because it is bound into the payload's AES-GCM AAD.
/// </summary>
public record CreateSecretRequest(
    Guid Id,
    Guid VaultId,
    string Name,
    string? Description,
    string SecretType,
    string? Provider,
    string? Environment,
    byte[] EncryptedPayload,
    byte[] Nonce,
    byte[] AuthTag,
    int EncryptionVersion,
    DateTime? ExpiresAt,
    IReadOnlyList<Guid>? TagIds);

/// <summary>
/// Payload fields are optional: omit them for a metadata-only edit. When a new payload is supplied,
/// the previous payload is kept as an encrypted version in the same transaction.
/// </summary>
public record UpdateSecretRequest(
    string Name,
    string? Description,
    string SecretType,
    string? Provider,
    string? Environment,
    DateTime? ExpiresAt,
    IReadOnlyList<Guid>? TagIds,
    byte[]? EncryptedPayload = null,
    byte[]? Nonce = null,
    byte[]? AuthTag = null,
    int? EncryptionVersion = null);

public record CreateSecretVersionRequest(byte[] EncryptedPayload, byte[] Nonce, byte[] AuthTag, int EncryptionVersion);

public record TagDto(Guid Id, string Name);

public record SecretSummary(
    Guid Id,
    Guid VaultId,
    string Name,
    string? Description,
    string SecretType,
    string? Provider,
    string? Environment,
    DateTime? ExpiresAt,
    DateTime CreatedAt,
    DateTime? ModifiedAt,
    bool IsArchived,
    IReadOnlyList<TagDto> Tags);

/// <summary>Metadata plus ciphertext. The API never returns decrypted payloads.</summary>
public record SecretResponse(
    Guid Id,
    Guid VaultId,
    string Name,
    string? Description,
    string SecretType,
    string? Provider,
    string? Environment,
    DateTime? ExpiresAt,
    DateTime CreatedAt,
    DateTime? ModifiedAt,
    bool IsArchived,
    IReadOnlyList<TagDto> Tags,
    byte[] EncryptedPayload,
    byte[] Nonce,
    byte[] AuthTag,
    int EncryptionVersion);

public record SecretVersionResponse(Guid Id, Guid SecretId, byte[] EncryptedPayload, byte[] Nonce, byte[] AuthTag,
    int EncryptionVersion, DateTime CreatedAt);

public class SecretQuery
{
    public Guid? VaultId { get; set; }
    public string? Search { get; set; }
    public string? SecretType { get; set; }
    public Guid? TagId { get; set; }
    public bool Archived { get; set; }
    public int? ExpiringWithinDays { get; set; }
    public int Page { get; set; } = 1;
    public int PageSize { get; set; } = 25;
}

public record TagRequest(string Name);
